import{at as e,it as t,t as n,yt as r}from"./chunks/framework.CgPcrqpH.js";var i=JSON.parse(`{"title":"Recording and Replaying","description":"","frontmatter":{"title":"Recording and Replaying"},"headers":[],"relativePath":"guides/the-manual/testing/record-and-replay.md","filePath":"guides/the-manual/testing/record-and-replay.md"}`),a={name:`guides/the-manual/testing/record-and-replay.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="recording-and-replaying" tabindex="-1">Recording and replaying <a class="header-anchor" href="#recording-and-replaying" aria-label="Permalink to “Recording and replaying”">​</a></h1><p>Holodeck runs in one of two modes. Recording writes fixtures to disk. Replay serves them back. Your test code is identical either way, so the mode comes from the environment instead.</p><h2 id="the-mode-is-compiled-into-the-test-build" tabindex="-1">The mode is compiled into the test build <a class="header-anchor" href="#the-mode-is-compiled-into-the-test-build" aria-label="Permalink to “The mode is compiled into the test build”">​</a></h2><p>The switch is a build-time flag, <code>SHOULD_RECORD</code>, defined in <code>@warp-drive/build-config</code> as:</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> SHOULD_RECORD</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Boolean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">CI</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> IS_RECORDING</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Recording is on whenever <code>CI</code> is unset, which covers every ordinary local run. Setting <code>IS_RECORDING</code> turns recording back on when <code>CI</code> is set, which is how you re-record from a CI environment on purpose.</p><div class="warning custom-block"><p class="custom-block-title">The value is baked into the bundle</p><p><code>SHOULD_RECORD</code> is inlined when the test bundle is built, not read when the test runs. Setting <code>CI</code> on a command that does not rebuild the bundle changes nothing, and the suite goes on recording. Set it on the build.</p></div><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CI</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:tests</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CI</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>In this repository, <code>pnpm test</code> at the root runs through turbo, and <code>CI</code> is one of the inputs turbo tracks for <code>build:tests</code>. Changing it invalidates the cached build, so a single command is enough.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CI</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">          # from the repository root</span></span></code></pre></div><p>Run that same command inside a test app&#39;s own directory and it skips turbo, reuses whatever <code>dist-test/</code> is already there, and quietly records.</p><h2 id="what-lands-on-disk" tabindex="-1">What lands on disk <a class="header-anchor" href="#what-lands-on-disk" aria-label="Permalink to “What lands on disk”">​</a></h2><p>The server writes fixtures under <code>.mock-cache/</code> in the directory the launching process started from, which is the test app&#39;s own directory.</p><p>Each fixture is a directory holding two files.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tests/json-api/.mock-cache/</span></span>
<span class="line"><span>  546c9e3a/                           the test id</span></span>
<span class="line"><span>    GET::users_1::0/                  method, URL, and request number</span></span>
<span class="line"><span>      res.meta.json                   status, statusText, headers, method, requestBody</span></span>
<span class="line"><span>      res.body.br                     the response payload, brotli-compressed</span></span></code></pre></div><p>The test id is a hash of the module name and the test name. Slashes in the URL become underscores. The last path segment is the request counter for that method and URL. When the mock matches on a request body, the file is named after a hash of that body instead of <code>res</code>.</p><p>Recording is deterministic. Re-recording an unchanged test reproduces the committed files byte for byte, so any diff under <code>.mock-cache/</code> means something in the test or the response really changed.</p><p>Two consequences are worth knowing before you go looking for a file.</p><p>Renaming a test changes its hash, so the old directory is orphaned and a new one is recorded. Nothing prunes the old one, and nothing reports it.</p><p>A URL with a query string puts that query string in a directory name, <code>?</code> included. Windows forbids <code>?</code> in a path, so fixtures for those URLs cannot be checked out on Windows.</p><h2 id="commit-the-fixtures" tabindex="-1">Commit the fixtures <a class="header-anchor" href="#commit-the-fixtures" aria-label="Permalink to “Commit the fixtures”">​</a></h2><p><code>.mock-cache</code> is source code. Commit it in the same change as the test that records it.</p><p>Committing them is what makes the cache useful. Git manages it, so a branch switch swaps fixtures and tests together, and a rebase or a CI run does no recording work at all because the files are already in the tree.</p><p>Nothing enforces this. No lint rule looks for it, and no CI check fails when a fixture is missing. The failure arrives later, as a broken test in the first environment that enforces replay.</p><h2 id="prove-replay-works-before-you-push" tabindex="-1">Prove replay works before you push <a class="header-anchor" href="#prove-replay-works-before-you-push" aria-label="Permalink to “Prove replay works before you push”">​</a></h2><p>A local run records what it needs, so a test with no committed fixture passes locally. Build and run in replay mode to find out whether the fixtures are really there.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CI</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">          # from the repository root</span></span></code></pre></div><p>Do this after adding or changing any test that mocks a request. It is the only local signal that tells a fixture you committed apart from one you recorded a moment ago.</p><h2 id="re-record-a-changed-test" tabindex="-1">Re-record a changed test <a class="header-anchor" href="#re-record-a-changed-test" aria-label="Permalink to “Re-record a changed test”">​</a></h2><p>Change the mock, run the suite locally, and holodeck records the new response over the old one. There is no separate command.</p><p>Delete the test&#39;s directory under <code>.mock-cache/</code> first when you want to be sure nothing stale survives. Run locally to record it fresh, then run in replay mode to confirm the result.</p><h2 id="use-record-locally-never-in-a-committed-test" tabindex="-1">Use <code>RECORD</code> locally, never in a committed test <a class="header-anchor" href="#use-record-locally-never-in-a-committed-test" aria-label="Permalink to “Use RECORD locally, never in a committed test”">​</a></h2><p>Every mock helper takes a <code>RECORD</code> option, and <code>mock</code> takes the same flag as its third argument. It is a per-request override. That one request records even while the rest of the suite replays.</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;users/1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, () </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ({ data: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }), { RECORD: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span></code></pre></div><p>Reach for it when a single fixture needs refreshing during a <code>CI=1</code> run, then delete it before you commit the test. A committed <code>RECORD: true</code> records in every environment, CI included, so the request it covers is never compared against its fixture again and a stale fixture goes unnoticed. <a href="/pr-preview/pr-9539/skills/holodeck/using-record">Use RECORD in Holodeck Mocks</a> walks through the refresh and what to look for in review.</p><p>Replay never calls a mock&#39;s response function, which is what makes a replayed suite cheap. A mock with <code>RECORD</code> is the one exception, because it is recorded rather than replayed.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to “Related”">​</a></h2><ul><li><a href="./writing-mocks">Writing mocks</a> covers declaring the mocks that produce these fixtures.</li><li><a href="./troubleshooting">Troubleshooting</a> covers what a missing or stale fixture looks like.</li></ul>`,38)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};